CREATE TABLE IF NOT EXISTS gis_identity_exception_resolutions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_feature_id uuid NOT NULL REFERENCES gis_spatial_features(id) ON DELETE CASCADE, target_feature_id uuid REFERENCES gis_spatial_features(id) ON DELETE SET NULL, resolution_type text NOT NULL, confidence text NOT NULL, auto_resolved boolean NOT NULL DEFAULT false, rationale text NOT NULL, evidence jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(source_feature_id));
CREATE INDEX IF NOT EXISTS idx_gis_exception_resolution_conf ON gis_identity_exception_resolutions(confidence,auto_resolved);